// Fonte de Verdade Única: Lê todas as configurações do .env
const fs = require('fs');
const pathEnv = './.env';

let weather_api_key = '';
let ollama_model = '';
let ollama_url = '';
let cidade_obra = '';
let smtp_host = '';
let smtp_port = '587';
let smtp_user = '';
let smtp_password = '';
let smtp_from_name = 'Assistente de Obra IA';

const project_path = fs.realpathSync('.');
const ts_inicio = Date.now();

try {
  if (fs.existsSync(pathEnv)) {
    const envRaw = fs.readFileSync(pathEnv, 'utf8');
    envRaw.split('\n').forEach(line => {
      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        const k = key.trim();
        const v = valueParts.join('=').trim().replace(/^[\"']|[\"']$/g, '');
        if (k === 'OLLAMA_MODEL') ollama_model = v;
        if (k === 'OLLAMA_URL') ollama_url = v;
        if (k === 'CIDADE_OBRA') cidade_obra = v;
        if (k === 'OPENWEATHER_API_KEY') weather_api_key = v;
        if (k === 'SMTP_HOST') smtp_host = v;
        if (k === 'SMTP_PORT') smtp_port = v;
        if (k === 'SMTP_USER') smtp_user = v;
        if (k === 'SMTP_PASSWORD') smtp_password = v;
        if (k === 'SMTP_FROM_NAME') smtp_from_name = v;
      }
    });
  }
} catch (e) { console.error('Erro ao ler .env', e); }

return {
  project_path,
  cidade: cidade_obra,
  weather_api_key,
  ollama_model,
  ollama_url,
  smtp_host,
  smtp_port,
  smtp_user,
  smtp_password,
  smtp_from_name,
  ts_inicio
};

// Lê o diário de obras, filtra o último dia com registro (dia anterior) e monta o prompt diário

const weatherData = $input.first().json;
const list = weatherData.list || [];
const config = $('Configurações Iniciais').first().json;

const dailyForecasts = {};
list.forEach(item => {
  const date = item.dt_txt.split(' ')[0];
  if (!dailyForecasts[date]) {
    dailyForecasts[date] = { temp_max: -999, precip: 0, desc: '' };
  }
  if (item.main.temp_max > dailyForecasts[date].temp_max) {
    dailyForecasts[date].temp_max = item.main.temp_max;
  }
  if (item.rain && item.rain['3h']) {
    dailyForecasts[date].precip += item.rain['3h'];
  }
  if (item.dt_txt.includes('12:00:00')) {
    dailyForecasts[date].desc = item.weather[0].description;
  }
});

const previsaoFormatada = Object.keys(dailyForecasts).slice(0, 5).map(d => {
  const day = dailyForecasts[d];
  const diaSemana = new Date(d + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'long', timeZone: 'America/Sao_Paulo' });
  const status = day.precip >= 5 || day.desc.toLowerCase().includes('chuva') ? 'CHUVA PREVISTA' : 'DIA SECO';
  return `  ${d} (${diaSemana}): ${day.desc ? '('+day.desc+') ' : ''}${day.precip.toFixed(1)}mm de chuva, máx ${day.temp_max.toFixed(1)}°C — ${status}`;
}).join('\n');

const fs = require('fs');
const diarioRaw = fs.readFileSync(
  `${config.project_path}/data/input/registros_exemplo.json`,
  'utf8'
);
const diario = JSON.parse(diarioRaw);
const obra     = diario.metadata.obra;
const cidade   = diario.metadata.cidade;
const todosCronologicos = diario.registros.sort((a, b) => new Date(a.data) - new Date(b.data));

const hoje = new Date();
hoje.setHours(0, 0, 0, 0);

// Seleciona o último dia com registro anterior a hoje (o "dia anterior" efetivo,
// pulando fins de semana/feriados sem apontamento)
const registrosPassados = todosCronologicos.filter(r => new Date(r.data + 'T12:00:00') < hoje);
const dataReferencia = registrosPassados.length > 0
  ? registrosPassados[registrosPassados.length - 1].data
  : null;

const registrosDia = dataReferencia
  ? todosCronologicos.filter(r => r.data === dataReferencia)
  : [];

const dataRefStr = dataReferencia
  ? new Date(dataReferencia + 'T12:00:00').toLocaleDateString('pt-BR')
  : '—';

const registrosFormatados = registrosDia.length > 0
  ? registrosDia.map(r => {
      const paralisacao = r.paralisada ? `PARALISADA — ${r.motivo_paralisacao}` : 'sem paralisação';
      return `  ${r.data} (${r.dia_semana}): ${r.etapa}, ${r.pct_etapa}% concluído, ${r.horas_trabalhadas}h trabalhadas, ${r.num_operarios} operários. Ocorrência: ${r.ocorrencia}. Status: ${paralisacao}.`;
    }).join('\n')
  : '  Nenhum registro encontrado para o dia anterior.';

const prompt = `Você é o assistente de planejamento diário do Engenheiro Ygor, responsável pela obra "${obra}", em ${cidade}.

Sua função é gerar um relatório diário prático, que o engenheiro possa ouvir em áudio ou ler, e que o ajude a planejar o dia de trabalho. O relatório deve ser escrito em texto contínuo e fluente, como se estivesse falando diretamente com o engenheiro. 

IMPORTANTE: Escreva o relatório em texto corrido, sem usar títulos em negrito, sem marcadores como asteriscos (*), sem hífens decorativos (-), sem símbolos ou abreviações. O texto deve ser natural para ser ouvido em voz alta (TTS), evitando qualquer caractere que cause ruído na leitura.

Os dados abaixo são as únicas fontes de informação que você deve usar. Não invente, não suponha, não extrapole.

DIÁRIO DE OBRAS — dia anterior (${dataRefStr}):
${registrosFormatados}

PREVISÃO DO TEMPO — hoje e próximos dias:
${previsaoFormatada}

O relatório deve conter:
1. O que aconteceu no dia anterior (atividades, progresso, operários, ocorrências).
2. Previsão do tempo de hoje e dos próximos dias e impacto na obra.
3. Sugestão técnica concreta de ação para hoje e os próximos dias.

Português brasileiro. Linguagem técnica, porém natural para locução.`;

return [{ json: { prompt, previsaoFormatada, registrosFormatados, obra, cidade, dataInicioStr: dataRefStr, dataFimStr: dataRefStr, dataRefStr } }];

const output = $input.first().json.response.trim();
const inputData = $input.first().json;
const hoje = new Date().toISOString().split('T')[0];

return [{
  json: {
    data_geracao: hoje,
    obra: inputData.obra || '',
    cidade: inputData.cidade || '',
    semana_referencia: `${inputData.dataInicioStr || ''} a ${inputData.dataFimStr || ''}`,
    relatorio_completo: output
  }
}];

const fs = require('fs');
const projectPath = $('Configurações Iniciais').first().json.project_path;
const tempPath = `${projectPath}/data/output/temp_tts.txt`;
const outputPath = `data/output/relatorio_${$json.data_geracao}.wav`;

const texto = $json.relatorio_completo;
fs.writeFileSync(tempPath, texto);

return [{
  json: {
    tts_temp_path: tempPath,
    output_path: outputPath,
    data_geracao: $json.data_geracao,
    relatorio_completo: $json.relatorio_completo
  }
}];

const fs = require('fs');
const projectPath = $('Configurações Iniciais').first().json.project_path;
const prevData = $('Preparar Texto para TTS').first().json;
const audioPath = $input.first().json.stdout?.trim() || 'N/D';

const hoje = new Date();
const semanaRef = hoje.toLocaleDateString('pt-BR'); // dia de referência (relatório diário)

const captionText = `🎧 Relatório Diário de Obra\n\n${prevData.relatorio_completo}`;
const captionFilePath = `${projectPath}/data/output/temp_caption.txt`;
fs.writeFileSync(captionFilePath, captionText);

return [{
  json: {
    data_geracao: hoje.toLocaleDateString('pt-BR'),
    semana_referencia: semanaRef,
    relatorio_completo: prevData.relatorio_completo,
    caminho_audio: audioPath,
    caption_file: captionFilePath,
    tts_temp_path: prevData.tts_temp_path,
    status: 'concluido'
  }
}];

// Logger de métricas de execução do pipeline
const fs = require('fs');
const projectPath = $('Configurações Iniciais').first().json.project_path;
const tsInicio = $('Configurações Iniciais').first().json.ts_inicio;
const tsFim = Date.now();

const logEntry = {
  timestamp: new Date().toISOString(),
  duracao_total_s: ((tsFim - tsInicio) / 1000).toFixed(2),
  canais: {
    telegram: { executado: true },
    email: { executado: true },
    csv: { executado: true }
  },
  status: 'concluido'
};

const logPath = `${projectPath}/data/output/execution_log.json`;
let logs = [];
try {
  if (fs.existsSync(logPath)) {
    logs = JSON.parse(fs.readFileSync(logPath, 'utf8'));
  }
} catch(e) {}
logs.push(logEntry);
fs.writeFileSync(logPath, JSON.stringify(logs, null, 2));

return [{ json: logEntry }];

// Error Handler Global — loga e notifica via Telegram
const fs = require('fs');
const error = $input.first().json;

const logEntry = {
  timestamp: new Date().toISOString(),
  error_message: error.message || JSON.stringify(error),
  node: error.node?.name || 'desconhecido',
  workflow: error.workflow?.name || 'Relatório Diário de Obra'
};

// Grava log de erros
try {
  const logPath = './data/output/error_log.json';
  let logs = [];
  if (fs.existsSync(logPath)) {
    logs = JSON.parse(fs.readFileSync(logPath, 'utf8'));
  }
  logs.push(logEntry);
  fs.writeFileSync(logPath, JSON.stringify(logs, null, 2));
} catch(e) { console.error('Falha ao gravar error_log', e); }

return [{ json: logEntry }];
